CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS venues(id TEXT PRIMARY KEY, name TEXT NOT NULL, pos_adapter TEXT NOT NULL DEFAULT 'mock');
CREATE TABLE IF NOT EXISTS checks(id TEXT PRIMARY KEY, venue_id TEXT NOT NULL REFERENCES venues(id), table_label TEXT NOT NULL, qr_code TEXT UNIQUE NOT NULL, visit_id TEXT NOT NULL, total_cents INTEGER NOT NULL CHECK(total_cents>=0), external_paid_cents INTEGER NOT NULL DEFAULT 0 CHECK(external_paid_cents>=0), revision INTEGER NOT NULL DEFAULT 1, active BOOLEAN NOT NULL DEFAULT TRUE, lines JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, venue_id TEXT NOT NULL REFERENCES venues(id), check_id TEXT NOT NULL REFERENCES checks(id), visit_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('guest','demo_admin','merchant')), expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY, venue_id TEXT NOT NULL REFERENCES venues(id), check_id TEXT NOT NULL REFERENCES checks(id), visit_id TEXT NOT NULL, session_hash TEXT NOT NULL REFERENCES sessions(token_hash), idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, check_revision INTEGER NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>0), tip_cents INTEGER NOT NULL CHECK(tip_cents>=0), currency TEXT NOT NULL CHECK(currency='ZAR'), provider TEXT NOT NULL, reference TEXT UNIQUE NOT NULL, funds_state TEXT NOT NULL DEFAULT 'PENDING' CHECK(funds_state IN ('PENDING','VERIFIED','FAILED','REVERSED')), pos_state TEXT NOT NULL DEFAULT 'NOT_SENT' CHECK(pos_state IN ('NOT_SENT','QUEUED','POSTED','RETRY','REVIEW')), reservation BOOLEAN NOT NULL DEFAULT TRUE, review_reason TEXT, checkout_url TEXT, created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, refunded_state TEXT NOT NULL DEFAULT 'NONE', UNIQUE(session_hash,idempotency_key));
CREATE INDEX IF NOT EXISTS payments_check ON payments(check_id);
CREATE TABLE IF NOT EXISTS provider_mock(reference TEXT PRIMARY KEY REFERENCES payments(reference), status TEXT NOT NULL, amount_cents INTEGER NOT NULL, currency TEXT NOT NULL, fault TEXT NOT NULL DEFAULT 'none');
CREATE TABLE IF NOT EXISTS pos_mock_posts(reference TEXT PRIMARY KEY REFERENCES payments(reference), venue_id TEXT NOT NULL, check_id TEXT NOT NULL, amount_cents INTEGER NOT NULL, tip_cents INTEGER NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_events(event_key TEXT PRIMARY KEY, provider TEXT NOT NULL, reference TEXT NOT NULL, payload_hash TEXT NOT NULL, deliveries INTEGER NOT NULL DEFAULT 1, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, payment_id TEXT NOT NULL REFERENCES payments(id), kind TEXT NOT NULL CHECK(kind IN ('VERIFY','POST_POS')), status TEXT NOT NULL DEFAULT 'READY', attempts INTEGER NOT NULL DEFAULT 0, due_at BIGINT NOT NULL, locked_until BIGINT NOT NULL DEFAULT 0, lease TEXT, last_error TEXT, UNIQUE(payment_id,kind));
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY, venue_id TEXT NOT NULL, payment_id TEXT, event TEXT NOT NULL, detail TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS refunds(id TEXT PRIMARY KEY, payment_id TEXT NOT NULL UNIQUE REFERENCES payments(id), venue_id TEXT NOT NULL, reason TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'REQUESTED', created_at BIGINT NOT NULL);
INSERT INTO schema_migrations(version,applied_at) VALUES(1,0) ON CONFLICT DO NOTHING;
